out<-"analysis/gamewell_sensitivity_2026-10-16"; input<-"analysis/gamewell_interval_dataset_2026-10-15/gamewell_daily_intervals.csv.gz"
d<-read.csv(gzfile(input),stringsAsFactors=FALSE,check.names=FALSE);linked<-function(x)tolower(trimws(as.character(x)))%in%c("true","1","yes");ok<-(linked(d$xbox_linked)|linked(d$nintendo_linked))&!is.na(d$interval_duration_hours)&!is.na(d$prior_affective_valence)&!is.na(d$later_affective_valence)&!is.na(d$recorded_linked_console_minutes_unique);base<-d[ok,,drop=FALSE];base$exposure_hours<-base$recorded_linked_console_minutes_unique/60
catfun<-function(lo,hi){if(lo>-.5&&hi<.5)"a"else if((hi<0||lo>0)&&(lo<-.5||hi>.5))"b"else if((hi<0||lo>0)&&lo>=-.5&&hi<=.5)"c"else"d"}
outrows<-list();ids<-c("7a_30h","7a_36h","7a_72h","7a_no_cutoff");limits<-c(30,36,72,Inf)
for(j in seq_along(ids)){h<-limits[j];z<-base[is.infinite(h)|base$interval_duration_hours<=h,,drop=FALSE];z$participant<-factor(as.character(z$participant_id));z$exposure_between<-ave(z$exposure_hours,z$participant,FUN=mean);z$exposure_within<-z$exposure_hours-z$exposure_between;z$prior_between<-ave(z$prior_affective_valence,z$participant,FUN=mean);z$prior_within<-z$prior_affective_valence-z$prior_between;z$log_interval_c<-log(z$interval_duration_hours)-mean(log(z$interval_duration_hours));z$later_valence<-z$later_affective_valence
 f<-lmerTest::lmer(later_valence~exposure_within+exposure_between+prior_within+prior_between+log_interval_c+(1|participant),data=z,REML=TRUE);cf<-summary(f)$coefficients;i<-match("exposure_within",rownames(cf));b<-unname(cf[i,"Estimate"]);se<-unname(cf[i,"Std. Error"]);df<-unname(cf[i,"df"]);ml<-b-qt(.975,df)*se;mu<-b+qt(.975,df)*se;ct<-as.data.frame(clubSandwich::coef_test(f,vcov="CR2",cluster=z$participant,test="Satterthwaite"));ci<-as.data.frame(clubSandwich::conf_int(f,vcov="CR2",cluster=z$participant,test="Satterthwaite"));ii<-match("exposure_within",rownames(ct));kk<-match("exposure_within",rownames(ci));crse<-as.numeric(ct[ii,"SE"]);crdf<-as.numeric(ct[ii,"df_Satt"]);cl<-as.numeric(ci[kk,"CI_L"]);cu<-as.numeric(ci[kk,"CI_U"]);usecr<-(cu-cl)>(mu-ml);wl<-if(usecr)cl else ml;wu<-if(usecr)cu else mu;msg<-f@optinfo$conv$lme4$messages;code<-f@optinfo$conv$opt;ri<-as.data.frame(lme4::VarCorr(f));risd<-ri$sdcor[ri$grp=="participant"&ri$var1=="(Intercept)"][1];vsd<-stats::sd(z$later_valence-ave(z$later_valence,z$participant,FUN=mean));xs<-stats::sd(z$exposure_within);outrows[[j]]<-data.frame(analysis_id=ids[j],cohort_definition=paste0("linked complete valence endpoints; interval <= ",if(is.infinite(h))"no cutoff"else paste0(h,"h")),n_intervals=nrow(z),n_participants=nlevels(z$participant),estimate=b,model_SE=se,model_df=df,model_CI_lower=ml,model_CI_upper=mu,CR2_SE=crse,CR2_df=crdf,CR2_CI_lower=cl,CR2_CI_upper=cu,wider_CI_lower=wl,wider_CI_upper=wu,category=catfun(wl,wu),convergence_code=paste(code,collapse=","),convergence_messages=if(length(msg))paste(msg,collapse=" | ")else"none",singular_fit=lme4::isSingular(f,tol=1e-4),random_intercept_SD=risd,residual_SD=sigma(f),exposure_within_SD=xs,within_person_valence_SD=vsd,stringsAsFactors=FALSE);rm(f)}
correct<-do.call(rbind,outrows);write.csv(correct,file.path(out,"SENSITIVITY_7A_CORRECTED.csv"),row.names=FALSE)
old<-read.csv(file.path(out,"SENSITIVITY_SUMMARY.csv"),stringsAsFactors=FALSE,check.names=FALSE);old<-old[!grepl("^7a_",old$analysis_id),,drop=FALSE]
new<-data.frame(analysis_id=correct$analysis_id,cohort_definition=correct$cohort_definition,n_intervals=correct$n_intervals,n_participants=correct$n_participants,estimate=correct$estimate,wider_CI_lower=correct$wider_CI_lower,wider_CI_upper=correct$wider_CI_upper,category=correct$category,fit_status="corrected cohort; one fit",singular_fit=correct$singular_fit,convergence_messages=correct$convergence_messages,stringsAsFactors=FALSE)
# The log-exposure estimate and CI in summary are expressed per 1 SD of within-person transformed exposure.
ix<-match("7b_i_log1p_minutes",old$analysis_id);orig<-read.csv(file.path(out,"SENSITIVITY_FIT_RESULTS.csv"),stringsAsFactors=FALSE);ir<-orig[orig$analysis_id=="7b_i_log1p_minutes",];old$estimate[ix]<-ir$estimate_per_1SD_exposure;old$wider_CI_lower[ix]<-ir$wider_CI_lower*ir$exposure_within_SD;old$wider_CI_upper[ix]<-ir$wider_CI_upper*ir$exposure_within_SD;old$category[ix]<-catfun(old$wider_CI_lower[ix],old$wider_CI_upper[ix]);old$cohort_definition[ix]<-"primary cohort; log(1+minutes), estimate and CI per 1 SD within-person exposure"
summ<-rbind(new,old);write.csv(summ,file.path(out,"SENSITIVITY_SUMMARY_CORRECTED.csv"),row.names=FALSE)
req<-summ[match(c(paste0("7a_",c("30h","36h","72h","no_cutoff")),"7b_i_log1p_minutes","7b_ii_cap_99","7e_min5_intervals","7f_no_zero_valence","7g_random_slope","7h_CR2_primary_no_refit"),summ$analysis_id),];rob<-all(!is.na(req$category)&req$category=="a")&&nrow(req)==10L;robtext<-if(rob)"Robust under all required prespecified sensitivities."else"Sensitive to one or more required prespecified analytic choices or unavailable fits."
report<-c("# GameWell sensitivity analyses — corrected report","","## Gate","","The six prefit hash checks passed for Plan v1, Addenda 1–4, and the interval dataset. The primary cohort gate reproduced 5,076 intervals, 371 participants, and 171 participants with exposure variation.","","## Correction to the initial sensitivity run","","The first run incorrectly applied the primary cohort's 48-hour maximum to the four 7a cohorts. Addendum 4 defines 7a from all linked intervals with both valence endpoints present and exposure non-missing, then applies 30h, 36h, 72h, or no cutoff. The initial 7a estimates in REPORT.md and SENSITIVITY_FIT_RESULTS.csv are invalid for 7a and must not be used. Four corrected 7a fits were run in one new correction script and are reported in SENSITIVITY_7A_CORRECTED.csv. The initial four fits were not deleted or overwritten; thus four extra fits were executed beyond one valid fit per 7a analysis. The corrected summary also reports 7b(i) estimate and CI on the specified per-1-SD scale.","","## Summary","","Estimates and confidence intervals describe associations with recorded linked-console play. The 7b(i) estimate and interval are per 1 SD of within-person log(1 + minutes); its SESOI is +/-0.8326 points per SD. Other model estimates and intervals are in valence points per hour.","","Analysis | Cohort | N intervals | N participants | Estimate | Wider CI | Category | Fit status / singular","---|---|---:|---:|---:|---|---|---")
for(i in seq_len(nrow(summ))){a<-summ[i,];es<-if(is.finite(a$estimate))sprintf("%.6f",a$estimate)else"not fitted";ci<-if(is.finite(a$wider_CI_lower))sprintf("[%.4f, %.4f]",a$wider_CI_lower,a$wider_CI_upper)else"not available";n<-if(is.finite(a$n_intervals))as.character(a$n_intervals)else"aggregate";np<-if(is.finite(a$n_participants))as.character(a$n_participants)else"aggregate";sg<-if(is.na(a$singular_fit))"n/a"else as.character(a$singular_fit);report<-c(report,sprintf("%s | %s | %s | %s | %s | %s | %s | %s; %s",a$analysis_id,a$cohort_definition,n,np,es,ci,ifelse(is.na(a$category),"none",a$category),a$fit_status,sg))}
report<-c(report,"","## Robustness","",robtext,"The label follows Addendum 4 item 4: all four 7a cohorts, both 7b variants, 7e, 7f, 7g, and 7h must be category (a).","","## Other prespecified outputs","","7c has no category by design. 7d fits only subsets meeting the 100-participant repeated-interval threshold; both-linked is counts only. 7i estimates were based on 371 successful leave-one-participant-out refits; the aggregate estimate distribution and category-change count are in LOO_AGGREGATE.csv. No participant IDs are in outputs.","","## Fit errors and limitations","","The only counts-only 7d group is both-linked (32 participants total; 25 with at least two intervals, below threshold). The repeated-measures fits are frequently singular. Limitations carried forward include incomplete interval-specific telemetry capture, Nintendo first-party-only coverage, ceiling compression and heterogeneous residual spread, and observational design. Results are associational, not causal. No primary model or life-satisfaction model was refitted.","","## Execution record","","The runner completed the prespecified models and LOO fits. The initial script generated an invalid 7a cohort and printed model summaries/aggregate output to the console, but no data rows or participant identifiers. R startup locale warnings and package/fit notices occurred. No packages were installed.")
writeLines(report,file.path(out,"REPORT_CORRECTED.md"),useBytes=TRUE);cat("Corrected 7a fits complete; corrected summary and report saved.\n")